#include <bits/stdc++.h>
using namespace std;

vector<int> intersection(vector<int>& nums1, vector<int>& nums2) {
    set<int> result;
    for (int a : nums1) {
        for (int b : nums2) {
            if (a == b) {
                result.insert(a);
                break;
            }
        }
    }
    return vector<int>(result.begin(), result.end());
}

int main() {
    vector<int> a1 = {1, 2, 2, 1}, b1 = {2, 2};
    for (int x : intersection(a1, b1)) cout << x << " ";
    cout << endl;
    vector<int> a2 = {4, 9, 5}, b2 = {9, 4, 9, 8, 4};
    for (int x : intersection(a2, b2)) cout << x << " ";
    cout << endl;
    return 0;
}

